noncomputable section

open Polynomial
open scoped BigOperators

namespace P1N1RungA

def ratPoly {K : Type*} [Field K] (p : K[X]) : RatFunc K :=
  algebraMap K[X] (RatFunc K) p

def ratConst {K : Type*} [Field K] (c : K) : RatFunc K :=
  ratPoly (C c)

def polePolynomial {K : Type*} [Field K] (a : K) : K[X] :=
  X - C a

def poleDen {K : Type*} [Field K] (a : K) (k : ℕ) : RatFunc K :=
  ratPoly ((polePolynomial a) ^ k)

def poleTerm {K : Type*} [Field K] (a : K) (k : ℕ) (c : K) : RatFunc K :=
  ratConst c / poleDen a k

def localPrincipalPart {K : Type*} [Field K] (a : K) (m : ℕ)
    (c : ℕ → K) : RatFunc K :=
  ∑ k ∈ Finset.Icc 1 m, poleTerm a k (c k)

def simpleResidueCoeff {K : Type*} [Field K] (c : ℕ → K) : K :=
  c 1

def IsRegularAt {K : Type*} [Field K] (f : RatFunc K) (a : K) : Prop :=
  ∃ p q : K[X], q.eval a ≠ 0 ∧ f = ratPoly p / ratPoly q

def HasLocalLaurentExpansion {K : Type*} [Field K] (f : RatFunc K)
    (a : K) (m : ℕ) (c : ℕ → K) (regular : RatFunc K) : Prop :=
  IsRegularAt regular a ∧ f = regular + localPrincipalPart a m c

def SimpleRootResidue {K : Type*} [Field K] (den num : K[X]) (a : K) : K :=
  den.eval a / num.derivative.eval a

theorem simple_root_residue_formula_from_local_expansion
    {K : Type*} [Field K] {den num : K[X]} {a : K}
    {m : ℕ} {c : ℕ → K} {regular : RatFunc K}
    (hroot : num.eval a = 0)
    (hsimple : num.derivative.eval a ≠ 0)
    (hexp :
      HasLocalLaurentExpansion
        (ratPoly den / ratPoly num) a m c regular) :
    SimpleRootResidue den num a = simpleResidueCoeff c := by
  sorry

end P1N1RungA
